package com.cryptostrategy.platform.evaluation.internal;import com.cryptostrategy.platform.backtesting.api.model.BacktestResult;import com.cryptostrategy.platform.evaluation.api.model.*;import com.cryptostrategy.platform.evaluation.api.port.in.EvaluateBacktestUseCase;import com.cryptostrategy.platform.evaluation.api.port.out.EvaluationResultStore;import java.util.Objects;public final class EvaluateBacktestService implements EvaluateBacktestUseCase{private final EvaluationResultStore store;private final DeterministicEvaluator evaluator=new DeterministicEvaluator();public EvaluateBacktestService(EvaluationResultStore store){this.store=Objects.requireNonNull(store);}@Override public EvaluationResult evaluate(BacktestResult result,MetricVersion metric,RankingVersion ranking){return store.save(evaluator.evaluate(result,metric,ranking));}}
